<div role="region" aria-label="Preview notice" data-testid="preview-banner" class="sticky top-0 z-[100] border-b-4 border-marigold bg-deep text-white shadow-lg"><div class="mx-auto flex max-w-7xl flex-wrap items-center gap-x-4 gap-y-1 px-4 py-2 text-sm"><strong class="rounded bg-marigold px-2 py-0.5 text-xs font-bold tracking-widest text-deep uppercase">ANTEPRIMA / PREVIEW — NOT LIVE</strong><span class="min-w-0 flex-1 truncate">{{ $banner['kindLabel'] }} · {{ $banner['title'] }} · {{ $bannerState }}{{ $banner['isFallback'] ? ' · No English version yet: showing Italian' : '' }}</span><nav aria-label="Preview language" class="flex gap-1">@foreach (\App\I18n\Locales::ALL as $bannerLocale)<a href="{{ $banner['previewPathFor'][$bannerLocale] }}"@if ($bannerLocale === $locale) aria-current="page"@endif class="rounded px-2 py-0.5 hover:bg-white/10 focus-visible:outline-2 focus-visible:outline-white aria-[current=page]:bg-white/20 aria-[current=page]:font-semibold">{{ \App\I18n\Locales::LABELS[$bannerLocale] }}</a>@endforeach</nav><a href="{{ $banner['editHref'] }}" class="rounded px-2 py-0.5 font-semibold underline underline-offset-4 hover:bg-white/10 focus-visible:outline-2 focus-visible:outline-white">Back to editor</a></div></div>
